import re

def parse_color(text):
    if not text.startswith('#'):
        raise ValueError("Invalid input: missing '#'")
    if len(text) != 7 and len(text) != 4:
        raise ValueError("Invalid input: length must be 7 or 4")
    if not re.match(r'^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$', text):
        raise ValueError("Invalid input: invalid hex characters")

    if len(text) == 7:
        r = int(text[1:3], 16)
        g = int(text[3:5], 16)
        b = int(text[5:7], 16)
    else:
        r = int(text[1] * 2, 16)
        g = int(text[2] * 2, 16)
        b = int(text[3] * 2, 16)

    return (r, g, b)

def slugify(text):
    text = text.lower()
    result = []
    in_non_alphanumeric = False

    for char in text:
        if char.isalnum():
            if in_non_alphanumeric:
                result.append('-')
                in_non_alphanumeric = False
            result.append(char)
        else:
            in_non_alphanumeric = True

    return ''.join(result).strip('-')

