        return []

    pairs.sort(key=lambda x: x[0])
    merged = [pairs[0]]

    for start, end in pairs[1:]:
        if start > end:
            raise ValueError("Interval start must be less than or equal to interval end.")
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

